<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import apiClient from "../services/api";
import { useAuth } from "../composables/useAuth";
type UserRole="ADMIN"|"SELLER";
interface ManagedUser{id:number|string;name:string;username:string;role:UserRole|string;active:boolean;}
const {user:currentUser}=useAuth();
const users=ref<ManagedUser[]>([]);const loading=ref(false);const submitting=ref(false);
const errorMessage=ref<string|null>(null);const feedbackMessage=ref<string|null>(null);
const showCreateModal=ref(false);const createdTempPassword=ref<string|null>(null);const copiedTempPassword=ref(false);
const createForm=reactive({name:"",username:"",role:"SELLER" as UserRole});
const showEditModal=ref(false);const editingUserId=ref<number|string|null>(null);
const editForm=reactive({name:"",username:"",role:"SELLER" as UserRole});
const statusTarget=ref<ManagedUser|null>(null);
const currentUserId=computed(()=>{const u=currentUser.value as Record<string,unknown>|null;return u?.id??null;});
const currentUsername=computed(()=>{const u=currentUser.value as Record<string,unknown>|null;return typeof u?.username==="string"?u.username.toLowerCase():"";});
const isSelfUser=(t:ManagedUser)=>(currentUserId.value!==null&&String(t.id)===String(currentUserId.value))||(Boolean(currentUsername.value)&&t.username.toLowerCase()===currentUsername.value);
const normalizeUser=(r:Record<string,unknown>):ManagedUser=>{const act=typeof r.active==="boolean"?r.active:typeof r.isActive==="boolean"?r.isActive:String(r.status??"active").toLowerCase()!=="inactive";return{id:(r.id as number|string)??"",name:String(r.name??r.fullName??r.nombre??""),username:String(r.username??r.usuario??""),role:String(r.role??r.rol??"SELLER").toUpperCase(),active:act};};
const fetchUsers=async()=>{loading.value=true;errorMessage.value=null;try{const {data}=await apiClient.get("/users");const list=Array.isArray(data)?data:Array.isArray(data?.users)?data.users:[];users.value=list.map((i:Record<string,unknown>)=>normalizeUser(i));}catch(e:unknown){errorMessage.value=(e as {userMessage?:string}).userMessage||"No fue posible cargar usuarios.";}finally{loading.value=false;}};
const openCreateModal=()=>{errorMessage.value=null;feedbackMessage.value=null;createdTempPassword.value=null;copiedTempPassword.value=false;createForm.name="";createForm.username="";createForm.role="SELLER";showCreateModal.value=true;};
const closeCreateModal=()=>{showCreateModal.value=false;createdTempPassword.value=null;copiedTempPassword.value=false;};
const handleCreateUser=async()=>{if(!createForm.name.trim()||!createForm.username.trim()){errorMessage.value="Completa nombre y usuario.";return;}submitting.value=true;errorMessage.value=null;try{const {data}=await apiClient.post("/users",{name:createForm.name.trim(),username:createForm.username.trim(),role:createForm.role});const raw=(data?.user??data) as Record<string,unknown>;const created=normalizeUser(raw);if(created.id||created.username){users.value.unshift(created);}else{await fetchUsers();}createdTempPassword.value=(data?.temporaryPassword as string|undefined)||(data?.tempPassword as string|undefined)||(data?.password as string|undefined)||"Temp#Flux2026";feedbackMessage.value="Usuario creado.";}catch(e:unknown){errorMessage.value=(e as {userMessage?:string}).userMessage||"Error al crear usuario.";}finally{submitting.value=false;}};
const copyTemporaryPassword=async()=>{if(!createdTempPassword.value)return;try{await navigator.clipboard.writeText(createdTempPassword.value);copiedTempPassword.value=true;setTimeout(()=>{copiedTempPassword.value=false;},2500);}catch{errorMessage.value="No se pudo copiar.";}};
const openEditModal=(t:ManagedUser)=>{errorMessage.value=null;feedbackMessage.value=null;editingUserId.value=t.id;editForm.name=t.name;editForm.username=t.username;editForm.role=(t.role==="ADMIN"?"ADMIN":"SELLER") as UserRole;showEditModal.value=true;};
const handleUpdateUser=async()=>{if(editingUserId.value===null)return;submitting.value=true;errorMessage.value=null;try{const {data}=await apiClient.put("/users/"+editingUserId.value,{name:editForm.name.trim(),username:editForm.username.trim(),role:editForm.role});const raw=(data?.user??data) as Record<string,unknown>;const idx=users.value.findIndex((u)=>String(u.id)===String(editingUserId.value));if(idx!==-1){users.value[idx]={...users.value[idx],...normalizeUser(raw),name:editForm.name.trim(),username:editForm.username.trim(),role:editForm.role};}showEditModal.value=false;feedbackMessage.value="Usuario actualizado.";}catch(e:unknown){errorMessage.value=(e as {userMessage?:string}).userMessage||"Error al actualizar.";}finally{submitting.value=false;}};
const requestToggleStatus=(t:ManagedUser)=>{if(isSelfUser(t)){errorMessage.value="No puedes desactivar tu propia cuenta.";return;}statusTarget.value=t;};
const confirmToggleStatus=async()=>{if(!statusTarget.value||isSelfUser(statusTarget.value)){statusTarget.value=null;return;}const t=statusTarget.value;const next=!t.active;submitting.value=true;errorMessage.value=null;try{await apiClient.patch("/users/"+t.id+"/status",{active:next});const idx=users.value.findIndex((u)=>String(u.id)===String(t.id));const row=users.value[idx];if(row){row.active=next;}feedbackMessage.value="Estado actualizado.";statusTarget.value=null;}catch(e:unknown){errorMessage.value=(e as {userMessage?:string}).userMessage||"Error al cambiar estado.";}finally{submitting.value=false;}};
onMounted(fetchUsers);
</script>
<template><section class="users-view"><header class="users-header"><div><h1>Gestión de Usuarios</h1><p>Administra cuentas de administradores y vendedores.</p></div><button type="button" class="btn btn-primary" @click="openCreateModal">+ Añadir usuario/vendedor</button></header><p v-if="feedbackMessage" class="alert alert-success">{{ feedbackMessage }}</p><p v-if="errorMessage" class="alert alert-error">{{ errorMessage }}</p><div v-if="loading" class="state-box">Cargando usuarios...</div><div v-else class="table-wrapper"><table class="users-table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-if="users.length===0"><td colspan="5" class="empty-cell">No hay usuarios registrados.</td></tr><tr v-for="u in users" :key="u.id"><td>{{ u.name }}</td><td>{{ u.username }}</td><td><span class="badge role-badge">{{ u.role }}</span></td><td><span :class="['badge',u.active?'status-active':'status-inactive']">{{ u.active?'Activo':'Inactivo' }}</span></td><td class="actions-cell"><button type="button" class="btn btn-secondary" @click="openEditModal(u)">Editar</button><button type="button" class="btn btn-warning" :disabled="isSelfUser(u)" @click="requestToggleStatus(u)">{{ u.active?'Desactivar':'Reactivar' }}</button></td></tr></tbody></table></div><div v-if="showCreateModal" class="modal-backdrop"><div class="modal-card"><h2>Añadir usuario / vendedor</h2><form v-if="!createdTempPassword" @submit.prevent="handleCreateUser" class="modal-form"><label>Nombre completo<input v-model="createForm.name" type="text" required /></label><label>Nombre de usuario<input v-model="createForm.username" type="text" required /></label><label>Rol<select v-model="createForm.role"><option value="SELLER">Vendedor (SELLER)</option><option value="ADMIN">Administrador (ADMIN)</option></select></label><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="closeCreateModal">Cancelar</button><button type="submit" class="btn btn-primary" :disabled="submitting">{{ submitting?'Guardando...':'Crear usuario' }}</button></div></form><div v-else class="temp-password-box"><p>Contraseña temporal generada:</p><div class="temp-password-display"><code>{{ createdTempPassword }}</code><button type="button" class="btn btn-primary" @click="copyTemporaryPassword">{{ copiedTempPassword?'¡Copiada!':'Copiar' }}</button></div><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="closeCreateModal">Cerrar</button></div></div></div></div><div v-if="showEditModal" class="modal-backdrop"><div class="modal-card"><h2>Editar usuario</h2><form @submit.prevent="handleUpdateUser" class="modal-form"><label>Nombre completo<input v-model="editForm.name" type="text" required /></label><label>Nombre de usuario<input v-model="editForm.username" type="text" required /></label><label>Rol<select v-model="editForm.role"><option value="SELLER">Vendedor (SELLER)</option><option value="ADMIN">Administrador (ADMIN)</option></select></label><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="showEditModal=false">Cancelar</button><button type="submit" class="btn btn-primary" :disabled="submitting">{{ submitting?'Guardando...':'Guardar cambios' }}</button></div></form></div></div><div v-if="statusTarget" class="modal-backdrop"><div class="modal-card"><h2>Confirmar cambio de estado</h2><p>¿Seguro que deseas <strong>{{ statusTarget.active?'desactivar':'reactivar' }}</strong> a <strong>{{ statusTarget.username }}</strong>?</p><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="statusTarget=null">Cancelar</button><button type="button" class="btn btn-warning" :disabled="submitting" @click="confirmToggleStatus">{{ submitting?'Procesando...':statusTarget.active?'Sí, desactivar':'Sí, reactivar' }}</button></div></div></div></section></template>
<style scoped>.users-view{padding:1.5rem}.users-header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1.25rem}.table-wrapper{overflow-x:auto}.users-table{width:100%;border-collapse:collapse}.users-table th,.users-table td{padding:.75rem;border-bottom:1px solid #e2e8f0;text-align:left}.actions-cell{display:flex;gap:.5rem}.badge{padding:.2rem .6rem;border-radius:999px;font-size:.85rem}.status-active{background:#dcfce7;color:#166534}.status-inactive{background:#fee2e2;color:#991b1b}.role-badge{background:#e0f2fe;color:#075985}.alert{padding:.75rem 1rem;border-radius:6px;margin-bottom:1rem}.alert-success{background:#dcfce7;color:#166534}.alert-error{background:#fee2e2;color:#991b1b}.modal-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.55);display:flex;align-items:center;justify-content:center;padding:1rem;z-index:50}.modal-card{background:#fff;color:#0f172a;padding:1.5rem;border-radius:10px;width:100%;max-width:440px}.modal-form{display:flex;flex-direction:column;gap:.9rem}.modal-form label{display:flex;flex-direction:column;gap:.35rem;font-size:.9rem}.modal-form input,.modal-form select{padding:.55rem .7rem;border:1px solid #cbd5e1;border-radius:6px}.temp-password-box{margin-top:.75rem}.temp-password-display{display:flex;align-items:center;justify-content:space-between;gap:.75rem;background:#f1f5f9;border:1px dashed #64748b;padding:.75rem 1rem;border-radius:8px;margin:.75rem 0 1rem}.temp-password-display code{font-size:1.05rem;font-weight:700}.modal-actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem}.btn{padding:.5rem .9rem;border:none;border-radius:6px;cursor:pointer}.btn:disabled{opacity:.5;cursor:not-allowed}.btn-primary{background:#2563eb;color:#fff}.btn-secondary{background:#e2e8f0;color:#1e293b}.btn-warning{background:#d97706;color:#fff}.empty-cell,.state-box{text-align:center;padding:1.5rem}</style>